import requests

def test_get_api_geocode_search_with_empty_or_unsupported_query():
    base_url = "http://localhost:8000"
    endpoint = "/api/geocode/search"
    url = base_url + endpoint
    headers = {
        "Authorization": "Bearer eyJhbGciOiJFUzI1NiIsImtpZCI6ImI4MTI2OWYxLTIxZDgtNGYyZS1iNzE5LWMyMjQwYTg0MGQ5MCIsInR5cCI6IkpXVCJ9..7tnorXc_v1GajgbKOx_eL1YOszeBUfjHR8eD_sTpsMVGd1byScCiaea2NrexKmTDL3dIlmobE5Mqry_s39Blkw"
    }
    timeout = 30

    # Define unsupported queries including empty string
    test_queries = ["", "!!!unsupported_query###", "1234567890", "@@@@", None]

    for query in test_queries:
        params = {}
        if query is not None:
            params["query"] = query

        try:
            response = requests.get(url, headers=headers, params=params, timeout=timeout)
        except requests.RequestException as e:
            assert False, f"Request failed: {e}"

        # As per the test case, expect a 4xx client error status code
        assert 400 <= response.status_code < 500, \
            f"Expected 4xx status code for query '{query}', got {response.status_code}"

test_get_api_geocode_search_with_empty_or_unsupported_query()